    if at then
        buffer = buffer * 64 + at - 1
        bits = bits + 6
        if bits >= 8 then
            bits = bits - 8
            local v = math.floor(buffer / (2 ^ bits)) % 256
            pos = pos + 1
            out[pos] = string.char((v - ((pos * 31 + 17) % 251)) % 256)
            buffer = buffer % (2 ^ bits)
        end
    end
end
local run, err = (loadstring or load)(table.concat(out))
if not run then error("CVortex SYI: decode failed: " .. tostring(err)) end
return run()
